import { test, expect } from 'bun:test';
import { createDb, registerUser } from '../src/users.js';
test('registers a user', () => {
  const db = createDb();
  const u = registerUser(db, 'ann@example.test');
  expect(u.email).toBe('ann@example.test');
  expect(db.users.get(u.id)).toEqual(u);
});
test('a second registration with the same email throws', () => {
  const db = createDb();
  registerUser(db, 'ann@example.test');
  expect(() => registerUser(db, 'ann@example.test')).toThrow();
  expect(db.users.size).toBe(1);
});
test('different emails are fine', () => {
  const db = createDb();
  registerUser(db, 'ann@example.test');
  registerUser(db, 'bo@example.test');
  expect(db.users.size).toBe(2);
});

