import { test, expect } from 'bun:test';
import { createDb, registerUser } from '../src/users.js';
test('case and surrounding spaces do not make a new email', () => {
  const db = createDb();
  registerUser(db, 'ann@example.test');
  expect(() => registerUser(db, 'Ann@Example.TEST')).toThrow();
  expect(() => registerUser(db, '  ann@example.test ')).toThrow();
  expect(db.users.size).toBe(1);
});
test('composed and decomposed Unicode forms are the same email', () => {
  const db = createDb();
  registerUser(db, 'caf\u00E9@example.test');
  expect(() => registerUser(db, 'cafe\u0301@example.test')).toThrow();
  expect(db.users.size).toBe(1);
});
